from ute_ue.robot_api.config_source import ConfigurationSource
from .taf_config import collector
from .translator import translate_taf_to_ute_ue


class TAFTranslatedConfigSource(ConfigurationSource):
    def pull(self):
        taf_config = collector.collect()
        ute_ue_config = translate_taf_to_ute_ue(taf_config)
        return ute_ue_config
